Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(pub)
WHERE (
  (toLower(pub.name) CONTAINS 'wired' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'wired'))
  AND (
    toLower(a.name) CONTAINS 'cyber monday'
    OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'cyber monday')
    OR EXISTS {
      MATCH (a)-[:MENTIONS]->(x:Product)
      WHERE toLower(x.name) CONTAINS 'sony'
         OR toLower(x.name) CONTAINS 'headphone'
         OR any(alias IN coalesce(x.aliases, []) WHERE toLower(alias) CONTAINS 'sony' OR toLower(alias) CONTAINS 'headphone')
    }
  )
) OR (
  (toLower(pub.name) CONTAINS 'fortune' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'fortune'))
  AND (
    toLower(a.name) CONTAINS 'market'
    OR toLower(a.name) CONTAINS 'rate'
    OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'market' OR toLower(alias) CONTAINS 'rate')
    OR EXISTS {
      MATCH (a)-[:MENTIONS|SAID|PARTICIPATED_IN]->(x:__Entity__)
      WHERE toLower(x.name) CONTAINS 'market'
         OR toLower(x.name) CONTAINS 'rate'
         OR toLower(x.name) CONTAINS 'participant'
         OR any(alias IN coalesce(x.aliases, []) WHERE toLower(alias) CONTAINS 'market' OR toLower(alias) CONTAINS 'rate' OR toLower(alias) CONTAINS 'participant')
    }
  )
)
OPTIONAL MATCH (a)-[r:MENTIONS|SAID|PARTICIPATED_IN]->(e:__Entity__)
RETURN a.name AS article, pub.name AS publisher,
       collect(DISTINCT CASE WHEN e IS NULL THEN null ELSE {name: e.name, relationship: type(r)} END) AS connected_people_entities
LIMIT 10
