Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(pub:Publisher),
      (a)-[:MENTIONS]->(person:Person)
WHERE (
  toLower(pub.name) CONTAINS 'techcrunch' OR
  any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch') OR
  toLower(pub.name) CONTAINS 'the verge' OR
  any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'the verge')
)
AND (
  toLower(person.name) CONTAINS 'sam bankman-fried' OR
  any(alias IN coalesce(person.aliases, []) WHERE toLower(alias) CONTAINS 'sam bankman-fried')
)
OPTIONAL MATCH (a)-[:MENTIONS]->(related)
RETURN DISTINCT pub.name AS publisher, a.name AS article, a.published_on AS published_on,
       person.name AS person, collect(DISTINCT related.name) AS related_entities
LIMIT 10
