Cypher query: MATCH (p:Publisher)<-[:PUBLISHED_BY]-(a:Article)
WHERE (toLower(p.name) CONTAINS 'the independent - life and style' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'the independent - life and style'))
  AND EXISTS {
    MATCH (a)-[:MENTIONS]->(e:__Entity__)
    WHERE toLower(e.name) CONTAINS 'taylor swift'
       OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'taylor swift')
       OR toLower(e.name) CONTAINS 'travis kelce'
       OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'travis kelce')
       OR toLower(e.name) CONTAINS 'arrowhead stadium'
       OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'arrowhead stadium')
  }
OPTIONAL MATCH (a)-[:MENTIONS]->(mentioned:__Entity__)
WITH a, collect(DISTINCT mentioned.name) AS mentioned_entities
OPTIONAL MATCH (a)-[:MENTIONS]->(related:Article)
RETURN a.name AS article, a.published_on AS published_on, mentioned_entities, collect(DISTINCT related.name) AS related_articles
